mapper.select:
SELECT * FROM ( SELECT w.WH_ID, w.WH_CODE, w.WH_NAME, w.ADDRESS, w.ADDRESS_DETAIL, w.REMARK, w.EMP_NO, w.POST_CODE, w.CREATED_AT, w.UPDATED_AT, e.EMP_NAME, e.TEL as empTel, ROW_NUMBER() OVER (ORDER BY w.WH_ID DESC) as rnum FROM WAREHOUSE w JOIN EMPLOYEE e ON w.EMP_NO = e.EMP_NO
AND (w.WH_CODE LIKE '%' || #{dto.keyword} || '%' OR w.WH_NAME LIKE '%' || #{dto.keyword} || '%')
) WHERE rnum BETWEEN #{dto.offset} + 1 AND #{dto.offset} + #{dto.size}

SELECT w.WH_ID, w.WH_CODE, w.WH_NAME, w.ADDRESS, w.ADDRESS_DETAIL, w.REMARK, w.EMP_NO, w.POST_CODE, w.CREATED_AT, w.UPDATED_AT, e.EMP_NAME, e.TEL as empTel, COALESCE(inv_summary.total_items, 0) as totalItems, COALESCE(inv_summary.current_stock, 0) as currentStock, COALESCE(inv_summary.expected_stock, 0) as expectedStock, COALESCE(inv_summary.allocated_stock, 0) as allocatedStock, COALESCE(inv_summary.available_stock, 0) as availableStock FROM ( SELECT * FROM ( SELECT w2.*, ROW_NUMBER() OVER (ORDER BY w2.WH_ID DESC) as rnum FROM WAREHOUSE w2
AND (w2.WH_CODE LIKE '%' || #{dto.keyword} || '%' OR w2.WH_NAME LIKE '%' || #{dto.keyword} || '%')
) WHERE rnum BETWEEN #{dto.offset} + 1 AND #{dto.offset} + #{dto.size} ) w JOIN EMPLOYEE e ON w.EMP_NO = e.EMP_NO LEFT JOIN ( SELECT WH_ID, COUNT(*) as total_items, SUM(CURRENT_QTY) as current_stock, SUM(EXPECTED_QTY) as expected_stock, SUM(ALLOCATED_QTY) as allocated_stock, SUM(CURRENT_QTY + EXPECTED_QTY - ALLOCATED_QTY) as available_stock FROM INVENTORY GROUP BY WH_ID ) inv_summary ON w.WH_ID = inv_summary.WH_ID ORDER BY w.WH_ID DESC
